package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_development_milestone",uniqueConstraints=@UniqueConstraint(name="uk_succ_dev_milestone_order",columnNames={"agency_id","plan_id","display_order"}))
public class SuccessionDevelopmentMilestone extends RspAuditedEntity{
 public enum Status{PLANNED,IN_PROGRESS,COMPLETED,NOT_MET}
 @Column(name="plan_id",nullable=false,length=36)private String planId;@Column(nullable=false,length=250)private String title;@Column(name="measurable_outcome",nullable=false,length=3000)private String measurableOutcome;@Column(name="due_date",nullable=false)private LocalDate dueDate;@Column(name="display_order",nullable=false)private int displayOrder;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="evidence_reference",length=1000)private String evidenceReference;@Column(name="employee_visible_feedback",length=3000)private String employeeVisibleFeedback;@Column(name="restricted_feedback",length=3000)private String restrictedFeedback;@Column(name="updated_by_actor",length=100)private String updatedByActor;@Column(name="status_updated_at")private Instant statusUpdatedAt;
 protected SuccessionDevelopmentMilestone(){}public SuccessionDevelopmentMilestone(String agency,String plan,String title,String outcome,LocalDate due,int order){super(agency);planId=requiredText(plan,"planId");this.title=requiredText(title,"title");measurableOutcome=requiredText(outcome,"measurableOutcome");dueDate=java.util.Objects.requireNonNull(due,"dueDate");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;status=Status.PLANNED;}
 public void updateStatus(Status next,String evidence,String visible,String restricted,String actor,Instant at){if(next==null)throw new IllegalArgumentException("status is required");if(status==Status.COMPLETED||status==Status.NOT_MET)throw new IllegalStateException("Final milestone status cannot be overwritten");if(next==Status.COMPLETED&&optionalText(evidence)==null)throw new IllegalArgumentException("Completed milestone requires evidence reference");status=next;evidenceReference=optionalText(evidence);employeeVisibleFeedback=optionalText(visible);restrictedFeedback=optionalText(restricted);updatedByActor=requiredText(actor,"actor");statusUpdatedAt=at;}
 public String getPlanId(){return planId;}public String getTitle(){return title;}public String getMeasurableOutcome(){return measurableOutcome;}public LocalDate getDueDate(){return dueDate;}public int getDisplayOrder(){return displayOrder;}public Status getStatus(){return status;}public String getEvidenceReference(){return evidenceReference;}public String getEmployeeVisibleFeedback(){return employeeVisibleFeedback;}public String getRestrictedFeedback(){return restrictedFeedback;}public String getUpdatedByActor(){return updatedByActor;}public Instant getStatusUpdatedAt(){return statusUpdatedAt;}
}
